import java.util.*;

public class HeapBasics {
    // ====== 1. Java PriorityQueue 基本用法 ======
    static void javaPriorityQueueDemo() {
        // 默认小顶堆
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        minHeap.offer(5); minHeap.offer(1); minHeap.offer(3);
        // poll 顺序：1, 3, 5
        while (!minHeap.isEmpty()) System.out.print(minHeap.poll() + " ");
        System.out.println();

        // 大顶堆：传 reverseOrder
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        maxHeap.offer(5); maxHeap.offer(1); maxHeap.offer(3);
        // poll 顺序：5, 3, 1
        while (!maxHeap.isEmpty()) System.out.print(maxHeap.poll() + " ");
        System.out.println();

        // 自定义比较器：按第二个元素排序（常见于合并 K 链表存 [值, 来源索引]）
        PriorityQueue<int[]> bySecond = new PriorityQueue<>((a, b) -> Integer.compare(a[1], b[1]));
        bySecond.offer(new int[]{100, 3});
        bySecond.offer(new int[]{200, 1});
        bySecond.offer(new int[]{300, 2});
        // poll 顺序按第二个元素：[200,1], [300,2], [100,3]
    }

    // ====== 2. 手写小顶堆（面试高频） ======
    static class MinHeap {
        private int[] heap;
        private int size;
        MinHeap(int capacity) { heap = new int[capacity]; }

        // 插入：放到末尾，上浮
        void offer(int val) {
            heap[size] = val;
            siftUp(size);
            size++;
        }

        // 取堆顶：末尾元素放堆顶，下沉
        int poll() {
            int top = heap[0];
            size--;
            heap[0] = heap[size]; // 末尾元素放堆顶
            if (size > 0) siftDown(0);
            return top;
        }

        int peek() { return heap[0]; }

        // 上浮：和父比较，违反堆序就交换
        private void siftUp(int i) {
            while (i > 0) {
                int parent = (i - 1) / 2;
                if (heap[i] < heap[parent]) { // 小顶堆：子 < 父则交换
                    swap(i, parent);
                    i = parent;
                } else break;
            }
        }

        // 下沉：和较小子比较，违反堆序就交换
        private void siftDown(int i) {
            while (true) {
                int left = 2 * i + 1, right = 2 * i + 2, smallest = i;
                if (left < size && heap[left] < heap[smallest]) smallest = left;
                if (right < size && heap[right] < heap[smallest]) smallest = right;
                if (smallest != i) {
                    swap(i, smallest);
                    i = smallest;
                } else break;
            }
        }

        private void swap(int a, int b) {
            int t = heap[a]; heap[a] = heap[b]; heap[b] = t;
        }
    }

    // ====== 3. Top-K 示例：用大小为 K 的小顶堆找前 K 大 ======
    static int[] topK(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(k);
        for (int n : nums) {
            if (minHeap.size() < k) {
                minHeap.offer(n);
            } else if (n > minHeap.peek()) {
                minHeap.poll();   // 弹出当前第 K 大中最小的
                minHeap.offer(n); // 更大的值入堆
            }
        }
        return minHeap.stream().mapToInt(Integer::intValue).toArray();
    }

    public static void main(String[] args) {
        javaPriorityQueueDemo();
        // Top-K: 前 3 大
        System.out.println(Arrays.toString(topK(new int[]{3,1,5,12,2,11}, 3)));
        // [5, 11, 12]（小顶堆内顺序不保证排序）
    }
}
